(()=>{
  const key='xiangye-memory-v1',read=()=>{try{return JSON.parse(localStorage.getItem(key)||'{}')}catch{return {}}};
  let dbData=read(),selected='',page=0,bookOpen=false,turning=false;
  const names={China:'中国',France:'法国',Egypt:'埃及',Japan:'日本',Italy:'意大利',Spain:'西班牙',Thailand:'泰国',Indonesia:'印尼',Malaysia:'马来西亚',Germany:'德国',Greece:'希腊',Antarctica:'南极'};
  const colors=['#efb9d7','#f5d59d','#a8d9e7','#c7df9d','#d5c2eb','#ef9d85'];
  const esc=v=>escapeHtml(String(v??''));
  const save=()=>{localStorage.setItem(key,JSON.stringify(dbData));window.dispatchEvent(new Event('xiangye:globe-data'))};
  const record=name=>dbData[name]||(dbData[name]={visited:false,color:'#efb9d7',regions:'',note:'',pages:[]});
  window.XIANGYE_MEMORY={countryColor:name=>{const r=dbData[names[name]||name];return r?.visited?r.color:''}};
  const oldProfile=renderProfile;
  function book(){if(!selected)return '';const r=record(selected),p=r.pages[page];const star='<svg viewBox="0 0 80 80" aria-hidden="true"><path d="M40 4C46 4 50 20 55 25S76 31 76 39 60 51 55 56 47 76 40 76 27 60 22 56 4 47 4 39 19 30 24 25 34 4 40 4Z" fill="currentColor"/><circle cx="33" cy="39" r="3" fill="#fff"/><circle cx="47" cy="39" r="3" fill="#fff"/><circle cx="33" cy="50" r="3" fill="#fff"/><circle cx="47" cy="50" r="3" fill="#fff"/></svg>';return `<section class="memory-book ${bookOpen?'is-open':'is-closed'}" id="memory-book"><div class="memory-book-head"><h2>${esc(selected)} · 旅行手帐</h2>${bookOpen?'<button type="button" data-memory="close">合上</button>':''}</div>${!bookOpen?`<button type="button" class="memory-cover" data-memory="unfold" aria-label="翻开${esc(selected)}旅行手帐"><span class="memory-cover-pattern" aria-hidden="true">✧ ☼ ❃ ✧ ❋ ☼ ✧</span><span class="memory-cover-title">${esc(selected)}<small>MY TRAVEL JOURNAL</small></span><span class="memory-cover-strap" aria-hidden="true"><i></i></span></button><p class="memory-cover-hint">轻触封面，翻开记忆</p>`:`<div class="memory-spread"><button type="button" class="memory-turn" data-memory="prev" ${page===0?'disabled':''} aria-label="上一页">←</button><div class="memory-page ${turning?'is-turning':''}" aria-live="polite">${p?`<img src="${p.photo}" alt="${esc(p.caption||selected+'的旅行照片')}"><div class="memory-page-note"><small>${esc(p.taken||p.added)} · ${esc(p.place||selected)}</small><p>${esc(p.caption||'那天的心情，留在这张照片里。')}</p></div>`:'<div class="memory-empty">这一页等你放进一张照片。</div>'}<button type="button" class="memory-insert" data-memory="insert">${star}<span>插入图片</span></button></div><button type="button" class="memory-turn" data-memory="next" ${page>=r.pages.length-1?'disabled':''} aria-label="下一页">→</button></div><p class="memory-page-count">第 ${r.pages.length?page+1:0} / ${r.pages.length} 页</p><form id="memory-photo-form" class="memory-photo-form" hidden><label>选择照片<input type="file" name="photo" accept="image/*" required></label><label>拍摄日期<input type="date" name="taken"></label><label>地点<input name="place" placeholder="例如：巴黎 · 塞纳河畔"></label><label>照片角落的小笔记<textarea name="caption" rows="2" maxlength="300" placeholder="那天你想记住什么？"></textarea></label><button type="submit">保存为新的一页</button></form>`}</section>`}
  renderProfile=function(){const original=oldProfile(),cards=Object.entries(dbData).map(([name,r])=>`<button type="button" class="memory-country" data-memory="open" data-country="${esc(name)}" style="--memory-color:${esc(r.color)}"><strong>${esc(name)}</strong><small>${(r.pages||[]).length} 页照片 · ${esc(r.regions||'地区待记录')}</small></button>`).join('');return `<section class="memory-world"><span class="page-overline">MY WORLD</span><h1>我的世界，慢慢着色</h1><p>转动地球，点一个去过的国家，给它颜色和记忆。</p><div class="globe-wrap memory-globe-wrap"><canvas id="memoryGlobeCanvas" aria-label="我的旅行地球，点击国家记录足迹"></canvas><div class="globe-zooms"><button data-globe-zoom="in" aria-label="放大地球">＋</button><button data-globe-zoom="out" aria-label="缩小地球">－</button></div></div><div id="memory-country-editor">${editor()}</div><div class="memory-shelf"><h2>我的旅行手帐</h2>${cards||'<p>还没有手帐。点地球上的一个国家，写下第一段记忆。</p>'}</div>${book()}</section><details class="memory-old"><summary>已保存的行程与应用信息</summary>${original}</details>`};
  function editor(){if(!selected)return '<p>选择地球上的国家，或从已保存的手帐继续翻阅。</p>';const r=record(selected);return `<form id="memory-country-form"><h2>${esc(selected)}</h2><label class="memory-visited"><input type="checkbox" name="visited" ${r.visited?'checked':''}> 我去过这里，点亮这个国家</label><label>我给它的颜色<input type="color" name="color" value="${esc(r.color)}"></label><div class="memory-swatches">${colors.map(c=>`<button type="button" data-memory-color="${c}" style="background:${c}" aria-label="选择颜色 ${c}"></button>`).join('')}</div><label>真正去过的城市或地区<input name="regions" value="${esc(r.regions)}" placeholder="例如：巴黎、里昂"></label><label>对这里的一句话感受<textarea name="note" rows="2" maxlength="500">${esc(r.note)}</textarea></label><button type="submit">保存足迹</button><button type="button" data-memory="open" data-country="${esc(selected)}">翻开手帐 ↗</button></form>`}
  document.addEventListener('xiangye:globe-select',e=>{if(state.view!=='profile')return;selected=names[e.detail.country]||e.detail.country||'';if(!selected)return;document.getElementById('memory-country-editor').innerHTML=editor()});
  document.addEventListener('click',e=>{const swatch=e.target.closest?.('[data-memory-color]');if(swatch){document.querySelector('#memory-country-form input[name="color"]').value=swatch.dataset.memoryColor;return}const b=e.target.closest?.('[data-memory]');if(!b)return;const a=b.dataset.memory;if(a==='open'){selected=b.dataset.country;page=0;bookOpen=false;render();document.getElementById('memory-book')?.scrollIntoView({behavior:'smooth'});return}if(a==='unfold'){bookOpen=true;render();document.getElementById('memory-book')?.scrollIntoView({behavior:'smooth'});return}if(a==='close'){bookOpen=false;render();return}if(a==='insert'){const form=document.getElementById('memory-photo-form');form.hidden=false;form.querySelector('input[type="file"]').click();return}if(a==='prev'||a==='next'){if(turning)return;const target=Math.max(0,Math.min(record(selected).pages.length-1,page+(a==='next'?1:-1)));if(target===page)return;turning=true;document.querySelector('.memory-page')?.classList.add(a==='next'?'flip-next':'flip-prev');setTimeout(()=>{page=target;turning=false;render()},330)}});
  document.addEventListener('submit',async e=>{if(e.target.id==='memory-country-form'){e.preventDefault();const form=new FormData(e.target),r=record(selected);r.visited=form.has('visited');r.color=String(form.get('color'));r.regions=String(form.get('regions')||'').trim();r.note=String(form.get('note')||'').trim();save();render();notify(r.visited?'这个国家已按你的颜色点亮。':'足迹已保存，地球保持素色。')}if(e.target.id==='memory-photo-form'){e.preventDefault();const f=new FormData(e.target),file=f.get('photo');if(!(file instanceof File)||!file.type.startsWith('image/'))return;const reader=new FileReader();reader.onload=()=>{const r=record(selected);r.pages.push({photo:String(reader.result),taken:String(f.get('taken')||''),added:new Date().toISOString().slice(0,10),place:String(f.get('place')||'').trim(),caption:String(f.get('caption')||'').trim()});page=r.pages.length-1;try{save();render();notify('这一页已保存。')}catch{r.pages.pop();notify('照片太大，当前浏览器无法保存；请换较小的照片。')}};reader.readAsDataURL(file)}});
  const oldRender=render;render=function(){oldRender();if(state.view==='profile')requestAnimationFrame(()=>window.mountXiangyeGlobe?.())};
})();
